import{magneticFigure}from './mag1-figures.js?v=20261023-physicscomplete01';
const entries=[['electromagnets','Current creates a solenoid field',['The coil carries a current.','Fields from individual turns reinforce.','A strong approximately uniform field forms inside.','An iron core can strengthen the field.']],['motors','A commutated coil keeps turning',['Current gives opposite side forces.','Their turning effect rotates the coil.','The split ring reverses current each half-turn.','The turning effect continues in the same rotational sense.']],['speakers','Electrical signal becomes sound',['Current in a magnetic field gives a force.','A changing current gives a changing force.','The attached cone moves back and forth.','Air-pressure variations carry sound away.']],['induction','Push in, then pull out',['A north pole enters the coil.','The changing field induces a pulse.','The pole’s motion reverses.','The induced pulse reverses with the change.']],['generators','Rotate a coil to generate AC',['Mechanical input turns the coil.','The field through the coil changes.','Induced polarity reverses over a rotation.','Slip rings connect the alternating output.']],['microphones','Sound becomes an electrical signal',['Sound pressure drives the diaphragm.','The attached coil moves in a magnetic field.','A varying potential difference is induced.','A connected circuit can carry a varying current.']],['transformers','One AC coil induces another',['Primary AC produces a changing field.','An iron core links the field through both coils.','The changing field induces secondary potential difference.','Turns ratio determines the ideal voltage ratio.']]];
export const mag1Films=Object.fromEntries(entries.map(([k,title,steps])=>['mag1-'+k,{title,steps,duration:16,render:p=>magneticFigure({kind:k,movie:true,progress:p,...(k==='electromagnets'?{a:'on',b:'iron'}:{})}),note:'Original schematic with enlarged coils, arrows and movement. Playback is slowed; prescribed rotation/vibration is not a prediction of speed, response or load. Reference wiring sets induction pulse sign. Coil fields, resistance, saturation, leakage and losses are simplified. A complete circuit is needed for induced current. The motor effect and generator effect are different energy-conversion pathways. Physical field mapping, device investigation and unrestricted diagrams remain separate evidence.'}]));
